def choose_move(observation):
    def pt(v, d=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return d

    def man(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def sign(z):
        return 0 if z == 0 else (1 if z > 0 else -1)

    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    s = pt(observation.get("self_position", (0, 0)), (0, 0))
    o = pt(observation.get("opponent_position", s), s)

    obstacles = set()
    for a in observation.get("obstacles", []):
        q = pt(a, None)
        if q is not None:
            obstacles.add(q)

    resources = []
    for a in observation.get("resources", []):
        q = pt(a, None)
        if q is not None:
            resources.append(q)

    path = []
    for a in observation.get("self_path", []):
        q = pt(a, None)
        if q is not None:
            path.append(q)

    territory = []
    for a in observation.get("territory", []):
        q = pt(a, None)
        if q is not None:
            territory.append(q)

    mode = observation.get("mode", "") or observation.get("task", "") or observation.get("game_type", "")
    mode = str(mode)

    def ok(nx, ny):
        return 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obstacles

    def best_step(targets, prefer_away=False):
        if not targets:
            return None
        best = None
        best_score = None
        for tx, ty in targets:
            dx = sign(tx - s[0])
            dy = sign(ty - s[1])
            cand = [(dx, dy), (dx, 0), (0, dy), (1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)]
            for mx, my in cand:
                nx, ny = s[0] + mx, s[1] + my
                if not ok(nx, ny):
                    continue
                score = man((nx, ny), (tx, ty))
                if prefer_away:
                    score = -score
                tie = (score, man((nx, ny), o), nx, ny, mx, my)
                if best_score is None or tie < best_score:
                    best_score = tie
                    best = (mx, my)
        return best

    # Determine likely objective.
    if "pursuit" in mode or "evasion" in mode:
        # Prefer distance from opponent, but move toward resources if clearly safe.
        cands = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
        best = (0, 0)
        best_score = None
        for mx, my in cands:
            nx, ny = s[0] + mx, s[1] + my
            if not ok(nx, ny):
                continue
            d_opp = man((nx, ny), o)
            d_res = 0
            if resources:
                d_res = min(man((nx, ny), r) for r in resources)
            score = (d_opp, -d_res, nx, ny, mx, my)
            if best_score is None or score > best_score:
                best_score = score
                best = (mx, my)
        return [best[0], best[1]]

    if "territory" in mode:
        # Bias toward unclaimed/edge territory: if self_path exists, extend it;
        # otherwise seek nearest resource/empty frontier while staying mobile.
        targets = []
        if path:
            targets = path
        elif territory:
            targets = territory
        elif resources:
            targets = resources
        step = best_step(targets)
        if step is not None:
            return [step[0], step[1]]

    if resources:
        # Go to nearest resource with obstacle-aware local fallback.
        target = min(resources, key=lambda r: (man(s, r), r[0], r[1]))
        dx = sign(target[0] - s[0])
        dy = sign(target[1] - s[1])
        cands = [(dx, dy), (dx, 0), (0, dy), (1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)]
        best = (0, 0)
        best_score = None
        for mx, my in cands:
            nx, ny = s[0] + mx, s[1] + my
            if not ok(nx, ny):
                continue
            score = (man((nx, ny), target), man((nx, ny), o), nx, ny, mx, my)
            if best_score is None or score < best_score:
                best_score = score
                best = (mx, my)
        return [best[0], best[1]]

    if path:
        step = best_step(path)
        if step is not None:
            return [step[0], step[1]]

    # Generic fallback: maximize freedom while not approaching opponent too much.
    moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
    best = (0, 0)
    best_score = None
    for mx, my in moves:
        nx, ny = s[0] + mx, s[1] + my
        if not ok(nx, ny):
            continue
        free = 0
        for ax, ay in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            tx, ty = nx + ax, ny + ay
            if ok(tx, ty):
                free += 1
        score = (free, man((nx, ny), o), nx, ny, mx, my)
        if best_score is None or score > best_score:
            best_score = score
            best = (mx, my)
    return [best[0], best[1]]

